      "speaker": "bot",
      "text": "Hello, आपको gasoline generator भी 220 से 240 की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "जी Madam."
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "मैं देख पा रही हूं आपको power capacity 1 KVA ही चाहिए ना?"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "बताइए generator type में क्या prefer करेंगे non silent silent या कोई और?"
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "नहीं loan पटेगी।"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "पचहत्तर हजार चाहिए तो।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "माफ़ कीजिए आपकी बात पूरी तरह समझ नहीं पाई।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "generator type में आपकी preference क्या है?"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "non-silent, silent, portable या open type?"
    },
    {
      "i": 13,
      "speaker": "caller",
      "text": "Open sir open."
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "ठीक है अब आपकी city और state भी बता दीजिए please."
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "एक kg चाहिए madam."
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "बहुत बढ़िया।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "अब अपनी city और state बता दीजिए please।"
    },
    {
      "i": 18,
      "speaker": "caller",
      "text": "तो madam मेरा उतना मालूम नहीं है कि क्या बोलते हैं।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "कोई बात नहीं आप जिस city में रहते हैं उसका नाम बता सकते हैं?"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "इससे seller आपकी मदद अच्छे से कर पाएंगे।"
    },
    {
      "i": 21,
      "speaker": "caller",
      "text": "मैं रहता हूँ जिला मेहरपुर, घर पर है जाफरपुर।"
    },
    {
      "i": 22,
      "speaker": "bot",
      "text": "आप Muzaffarpur Bihar से बोल रहे हैं ना?"
    },
    {
      "i": 23,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "बहुत बढ़िया।"
    },
    {
      "i": 25,
      "speaker": "bot",
      "text": "आप गिद्दू जी बोल रहे हैं ना?"
    },
    {
      "i": 26,
      "speaker": "caller",
      "text": "जी।"
    },
    {
      "i": 27,
      "speaker": "bot",
      "text": "आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 28,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 29,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    }
  ]
